const INTRO = "<div class=\"intro-box\">\n      <h3>📖 Що це за тренажер?</h3>\n      <p><b>Situational English</b> — це готові фрази, які тобі знадобляться в <b>реальних ситуаціях життя</b>: коли ти в кафе, готелі, у лікаря, в аеропорту. Тут немає теорії граматики — тільки <b>«що сказати, коли...»</b>.</p>\n      <p>🎯 <b>Кожна ситуація має 4 типи фраз:</b></p>\n      <p>🔵 <b>YOU</b> — що ти кажеш сам (твої фрази)<br>\n      🟠 <b>THEM</b> — що тобі може сказати співрозмовник (треба розуміти!)<br>\n      🟢 <b>USEFUL</b> — додатково корисні фрази для ситуації<br>\n      🔴 <b>⚠️ WARNING</b> — типові помилки або те, чого <b>НЕ</b> казати</p>\n      <p>💬 <b>+ Готовий діалог-зразок</b> для кожної ситуації — повний мікро-сценарій.</p>\n    </div>\n\n    <div class=\"intro-box\" style=\"background:linear-gradient(135deg,#ede9fe,#ddd6fe);border-color:#7c3aed\">\n      <h3 style=\"color:#4c1d95\">💡 Як ефективно вчити (3 кроки):</h3>\n      <p style=\"color:#5b21b6\"><b>1. Прочитай ситуацію</b> — переглянь усі 4 ролі (YOU, THEM, USEFUL, ⚠️).</p>\n      <p style=\"color:#5b21b6\"><b>2. Промов вголос</b> ключові «YOU» фрази 3 рази — це м'язова пам'ять.</p>\n      <p style=\"color:#5b21b6\"><b>3. Уяви себе в цій ситуації</b> — який діалог би вийшов? Програй його у голові.</p>\n      <p style=\"color:#5b21b6\"><b>4. Перевір картками</b> — повторюй ті, які забув, через 1-3-7 днів.</p>\n    </div>\n\n    <h3 style=\"margin-bottom:10px;color:#78350f\">🎬 15 ситуацій — клацай на ту, що цікавить:</h3>\n    <div class=\"sit-grid\"></div>";
